4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	
6	/** self-link: Return 'selfLink' = '/api/owners/' followed by the new owner id.... */
7	class AcceptanceTest extends AcceptanceBase {
