11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "salutation", expression = "java(Salutation.of(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CustomerCode.checkDigit(owner.getCustomerCode()))")
25	    @Mapping(target = "membershipNumber", expression = "java(org.springframework.samples.petclinic.model.MembershipNumber.of(owner))")
26	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.model.FiscalYear.of(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(org.springframework.samples.petclinic.model.MembershipLevel.points(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.model.MembershipLevel.of(owner))")
29	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.model.CustomerCode.region(owner.getCustomerCode()))")
30	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.Regions.timezoneOf(org.springframework.samples.petclinic.model.CustomerCode.region(owner.getCustomerCode())))")
31	    @Mapping(target = "contactPreference", expression = "java(ContactPreference.of(owner))")
32	    @Mapping(target = "ageBand", expression = "java(AgeBand.of(owner))")
33	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.model.OwnerIdentity.of(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.model.OwnerTelephone.toDisplay(owner.getTelephone()))")
35	    @Mapping(target = "bulkSignupWarning", ignore = true)
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    Owner toOwner(OwnerDto ownerDto);
39	
40	    @Mapping(target = "id", ignore = true)
41	    @Mapping(target = "pets", ignore = true)
42	    Owner toOwner(OwnerFieldsDto ownerDto);
43	
44	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
45	
46	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
47	
48	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
49	        OwnerPageDto ownerPageDto = new OwnerPageDto();
50	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
51	        ownerPageDto.setPage(ownerPage.getNumber());
52	        ownerPageDto.setSize(ownerPage.getSize());
53	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
54	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
55	        return ownerPageDto;
56	    }
57	}
