249	    protected void setPetsInternal(Set<Pet> pets) {
250	        this.pets = pets;
251	    }
252	
253	    public List<Pet> getPets() {
254	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
255	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
256	        return Collections.unmodifiableList(sortedPets);
257	    }
258	
259	    public void setPets(List<Pet> pets) {
260	        this.pets = new HashSet<>(pets);
261	    }
262	
263	    public void addPet(Pet pet) {
264	        getPetsInternal().add(pet);
265	        pet.setOwner(this);
266	    }
267	
268	    /**
269	     * Return the Pet with the given name, or null if none found for this Owner.
270	     *
271	     * @param name to test
272	     * @return true if pet name is already in use
273	     */
274	    public Pet getPet(String name) {
275	        return getPet(name, false);
276	    }
277	
278	    /**
279	     * Return the Pet with the given name, or null if none found for this Owner.
280	     *
281	     * @param name to test
282	     * @return true if pet name is already in use
283	     */
284	    public Pet getPet(String name, boolean ignoreNew) {
285	        name = name.toLowerCase();
286	        for (Pet pet : getPetsInternal()) {
287	            if (!ignoreNew || !pet.isNew()) {
288	                String compName = pet.getName();
289	                compName = compName.toLowerCase();
290	                if (compName.equals(name)) {
291	                    return pet;
292	                }
293	            }
294	        }
295	        return null;
296	    }
297	
298	    public Pet getPet(Integer petId) {
299	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
300	    }
301	
302	    @Override
303	    public String toString() {
304	        return new ToStringCreator(this)
305	
306	            .append("id", this.getId())
307	            .append("new", this.isNew())
308	            .append("lastName", this.getLastName())
309	            .append("firstName", this.getFirstName())
310	            .append("address", this.address)
311	            .append("city", this.city)
312	            .append("telephone", this.telephone)
313	            .toString();
314	    }
315	}
